import express from "express";
import http from "http";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";
import { createServer as createViteServer } from "vite";

interface RoomPlayer {
  id: string;
  name: string;
  slot: number; // 0, 1, 2, 3
  color: string;
  ready: boolean;
  x: number;
  y: number;
  direction: string;
  isMoving: boolean;
  isAlive: boolean;
  score: number;
  ws: WebSocket;
}

interface RoomBomb {
  id: string;
  ownerId: string;
  tileX: number;
  tileY: number;
  timer: number;
  range: number;
}

interface Room {
  id: string;
  name: string;
  hostId: string;
  players: Map<string, RoomPlayer>;
  status: "waiting" | "starting" | "playing" | "game_over";
  mapSeed: number;
  arenaGrid: number[][]; // 13 rows x 15 cols: 0: empty, 1: wall, 2: brick
  bombs: RoomBomb[];
  winnerId: string | null;
  round: number;
  timer: number;
}

const rooms = new Map<string, Room>();

const app = express();
const PORT = 3000;

app.use(express.json());

// API Routes
app.get("/api/health", (_req, res) => {
  res.json({ status: "ok", activeRooms: rooms.size });
});

app.get("/api/rooms", (_req, res) => {
  const roomList = Array.from(rooms.values()).map((r) => ({
    id: r.id,
    name: r.name,
    playerCount: r.players.size,
    status: r.status,
  }));
  res.json({ rooms: roomList });
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

function generateArenaGrid(seed: number): number[][] {
  const ROWS = 13;
  const COLS = 15;
  const grid: number[][] = [];
  let s = seed;
  const pseudoRandom = () => {
    s = (s * 9301 + 49297) % 233280;
    return s / 233280;
  };

  for (let r = 0; r < ROWS; r++) {
    const row: number[] = [];
    for (let c = 0; c < COLS; c++) {
      if (r === 0 || r === ROWS - 1 || c === 0 || c === COLS - 1) {
        row.push(1); // Border wall
      } else if (r % 2 === 0 && c % 2 === 0) {
        row.push(1); // Fixed pillar
      } else {
        // Safe spawn corners
        const isCorner =
          (r <= 2 && c <= 2) ||
          (r <= 2 && c >= COLS - 3) ||
          (r >= ROWS - 3 && c <= 2) ||
          (r >= ROWS - 3 && c >= COLS - 3);

        if (!isCorner && pseudoRandom() < 0.65) {
          row.push(2); // Brick
        } else {
          row.push(0); // Empty
        }
      }
    }
    grid.push(row);
  }
  return grid;
}

function broadcastToRoom(room: Room, message: object, excludeWs?: WebSocket) {
  const payload = JSON.stringify(message);
  for (const player of room.players.values()) {
    if (player.ws !== excludeWs && player.ws.readyState === WebSocket.OPEN) {
      player.ws.send(payload);
    }
  }
}

wss.on("connection", (ws) => {
  let currentRoomId: string | null = null;
  let playerId: string | null = null;

  ws.on("message", (raw) => {
    try {
      const data = JSON.parse(raw.toString());
      const { type } = data;

      if (type === "create_room") {
        const roomId = Math.random().toString(36).substring(2, 6).toUpperCase();
        playerId = "p_" + Math.random().toString(36).substring(2, 9);
        currentRoomId = roomId;

        const seed = Math.floor(Math.random() * 100000);
        const newRoom: Room = {
          id: roomId,
          name: (data.roomName || "Arena") + " #" + roomId,
          hostId: playerId,
          players: new Map(),
          status: "waiting",
          mapSeed: seed,
          arenaGrid: generateArenaGrid(seed),
          bombs: [],
          winnerId: null,
          round: 1,
          timer: 180,
        };

        const player: RoomPlayer = {
          id: playerId,
          name: data.playerName || "Bomber 1",
          slot: 0,
          color: "#ffffff", // White
          ready: true,
          x: 1,
          y: 1,
          direction: "down",
          isMoving: false,
          isAlive: true,
          score: 0,
          ws,
        };

        newRoom.players.set(playerId, player);
        rooms.set(roomId, newRoom);

        ws.send(
          JSON.stringify({
            type: "room_joined",
            roomId,
            playerId,
            slot: 0,
            isHost: true,
            room: {
              id: newRoom.id,
              name: newRoom.name,
              status: newRoom.status,
              mapSeed: newRoom.mapSeed,
              arenaGrid: newRoom.arenaGrid,
              players: Array.from(newRoom.players.values()).map((p) => ({
                id: p.id,
                name: p.name,
                slot: p.slot,
                color: p.color,
                ready: p.ready,
                score: p.score,
              })),
            },
          })
        );
      } else if (type === "join_room") {
        const roomId = (data.roomId || "").trim().toUpperCase();
        const room = rooms.get(roomId);

        if (!room) {
          ws.send(JSON.stringify({ type: "error", message: "Sala no encontrada." }));
          return;
        }

        if (room.players.size >= 4) {
          ws.send(JSON.stringify({ type: "error", message: "La sala está llena (máx 4)." }));
          return;
        }

        if (room.status === "playing") {
          ws.send(JSON.stringify({ type: "error", message: "La partida ya ha comenzado." }));
          return;
        }

        playerId = "p_" + Math.random().toString(36).substring(2, 9);
        currentRoomId = roomId;

        const colors = ["#ffffff", "#222222", "#ef4444", "#3b82f6"];
        const usedSlots = new Set(Array.from(room.players.values()).map((p) => p.slot));
        let slot = 0;
        while (usedSlots.has(slot)) slot++;

        const spawnPos = [
          { x: 1, y: 1 },
          { x: 13, y: 11 },
          { x: 13, y: 1 },
          { x: 1, y: 11 },
        ];

        const player: RoomPlayer = {
          id: playerId,
          name: data.playerName || `Bomber ${slot + 1}`,
          slot,
          color: colors[slot % colors.length],
          ready: false,
          x: spawnPos[slot]?.x || 1,
          y: spawnPos[slot]?.y || 1,
          direction: "down",
          isMoving: false,
          isAlive: true,
          score: 0,
          ws,
        };

        room.players.set(playerId, player);

        ws.send(
          JSON.stringify({
            type: "room_joined",
            roomId,
            playerId,
            slot,
            isHost: room.hostId === playerId,
            room: {
              id: room.id,
              name: room.name,
              status: room.status,
              mapSeed: room.mapSeed,
              arenaGrid: room.arenaGrid,
              players: Array.from(room.players.values()).map((p) => ({
                id: p.id,
                name: p.name,
                slot: p.slot,
                color: p.color,
                ready: p.ready,
                score: p.score,
              })),
            },
          })
        );

        broadcastToRoom(
          room,
          {
            type: "player_joined",
            player: {
              id: player.id,
              name: player.name,
              slot: player.slot,
              color: player.color,
              ready: player.ready,
              score: player.score,
            },
          },
          ws
        );
      } else if (type === "toggle_ready" && currentRoomId && playerId) {
        const room = rooms.get(currentRoomId);
        if (!room) return;
        const player = room.players.get(playerId);
        if (player) {
          player.ready = !player.ready;
          broadcastToRoom(room, {
            type: "player_ready_changed",
            playerId,
            ready: player.ready,
          });
        }
      } else if (type === "start_game" && currentRoomId && playerId) {
        const room = rooms.get(currentRoomId);
        if (!room || room.hostId !== playerId) return;

        room.status = "playing";
        room.mapSeed = Math.floor(Math.random() * 100000);
        room.arenaGrid = generateArenaGrid(room.mapSeed);
        room.timer = 180;

        const spawnPos = [
          { x: 1, y: 1 },
          { x: 13, y: 11 },
          { x: 13, y: 1 },
          { x: 1, y: 11 },
        ];

        for (const p of room.players.values()) {
          p.isAlive = true;
          p.x = spawnPos[p.slot]?.x ?? 1;
          p.y = spawnPos[p.slot]?.y ?? 1;
          p.direction = "down";
          p.isMoving = false;
        }

        broadcastToRoom(room, {
          type: "game_started",
          mapSeed: room.mapSeed,
          arenaGrid: room.arenaGrid,
          players: Array.from(room.players.values()).map((p) => ({
            id: p.id,
            slot: p.slot,
            x: p.x,
            y: p.y,
            isAlive: p.isAlive,
          })),
        });
      } else if (type === "player_move" && currentRoomId && playerId) {
        const room = rooms.get(currentRoomId);
        if (!room || room.status !== "playing") return;
        const player = room.players.get(playerId);
        if (!player || !player.isAlive) return;

        player.x = data.x;
        player.y = data.y;
        player.direction = data.direction;
        player.isMoving = data.isMoving;

        broadcastToRoom(
          room,
          {
            type: "player_moved",
            playerId,
            x: player.x,
            y: player.y,
            direction: player.direction,
            isMoving: player.isMoving,
          },
          ws
        );
      } else if (type === "bomb_placed" && currentRoomId && playerId) {
        const room = rooms.get(currentRoomId);
        if (!room || room.status !== "playing") return;
        broadcastToRoom(room, {
          type: "bomb_placed",
          bomb: data.bomb,
        });
      } else if (type === "brick_destroyed" && currentRoomId) {
        const room = rooms.get(currentRoomId);
        if (!room) return;
        if (
          room.arenaGrid[data.tileY] &&
          room.arenaGrid[data.tileY][data.tileX] === 2
        ) {
          room.arenaGrid[data.tileY][data.tileX] = 0;
        }
        broadcastToRoom(room, {
          type: "brick_destroyed",
          tileX: data.tileX,
          tileY: data.tileY,
          powerUp: data.powerUp,
        });
      } else if (type === "player_died" && currentRoomId) {
        const room = rooms.get(currentRoomId);
        if (!room || room.status !== "playing") return;
        const deadPlayer = room.players.get(data.playerId);
        if (deadPlayer) {
          deadPlayer.isAlive = false;
        }

        broadcastToRoom(room, {
          type: "player_died",
          playerId: data.playerId,
          killerId: data.killerId,
        });

        // Check if 1 or 0 players remain alive
        const alivePlayers = Array.from(room.players.values()).filter(
          (p) => p.isAlive
        );
        if (alivePlayers.length <= 1) {
          const winner = alivePlayers[0] || null;
          if (winner) {
            winner.score = (winner.score || 0) + 1;
          }
          room.status = "game_over";
          broadcastToRoom(room, {
            type: "round_over",
            winnerId: winner ? winner.id : null,
            winnerName: winner ? winner.name : "Empate",
            players: Array.from(room.players.values()).map((p) => ({
              id: p.id,
              score: p.score,
            })),
          });
        }
      }
    } catch (err) {
      console.error("WS error handling message:", err);
    }
  });

  ws.on("close", () => {
    if (currentRoomId && playerId) {
      const room = rooms.get(currentRoomId);
      if (room) {
        room.players.delete(playerId);
        if (room.players.size === 0) {
          rooms.delete(currentRoomId);
        } else {
          if (room.hostId === playerId) {
            const nextHost = Array.from(room.players.values())[0];
            room.hostId = nextHost.id;
          }
          broadcastToRoom(room, {
            type: "player_left",
            playerId,
            newHostId: room.hostId,
          });
        }
      }
    }
  });
});

async function start() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  server.listen(PORT, "0.0.0.0", () => {
    console.log(`Dyna Blaster server running on http://0.0.0.0:${PORT}`);
  });
}

start();
